describe('File Download Export Functionality', () => {
  beforeEach(() => {
    cy.visit('/data-table');
  });

  it('should trigger file download when export button is clicked', () => {
    // Setup: intercept the export API call
    cy.intercept('GET', '/api/data/export', {
      statusCode: 200,
      headers: {
        'content-type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'content-disposition': 'attachment; filename="data-export.xlsx"'
      },
      body: '...'
    }).as('exportData');

    // Verify data table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Click the export button
    cy.get('[data-testid="export-button"]').click();

    // Wait for the API call
    cy.wait('@exportData');

    // Verify download prompt or file appears
    cy.get('[data-testid="download-status"]').should('contain', 'Export successful');

    // Verify download link/button is visible
    cy.get('[data-testid="download-link"]').should('be.visible');

    // Verify download link has correct href
    cy.get('[data-testid="download-link"]').should('have.attr', 'href');
  });

  it('should handle export failure and display error message', () => {
    // Setup: intercept the export API call with error
    cy.intercept('GET', '/api/data/export', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('exportDataError');

    // Verify data table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Click the export button
    cy.get('[data-testid="export-button"]').click();

    // Wait for the failed API call
    cy.wait('@exportDataError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Export failed');

    // Verify download link is not visible
    cy.get('[data-testid="download-link"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
